), saved AS(
 INSERT INTO public.beagu_survey_geography_comparisons_v1
 (survey_year,question_id,scope,region,mode_option,mean_option,comparison_kind,source_book,method_note,review_status)
 SELECT * FROM source
 WHERE length(mode_option)<=130 AND length(method_note)<=220 AND length(source_book)<=90
 ON CONFLICT(survey_year,question_id,scope,region) DO NOTHING
 RETURNING survey_year,question_id,scope,region
)
SELECT count(*) AS inserted,count(*) FILTER (WHERE scope='national') AS national_added,
 count(*) FILTER(WHERE scope='regional') AS regional_added FROM saved;